/* ========== مزامنة المندوبات من الانفو (قراءة فقط) — إضافة 2026-11 ==========
 * يقرا أعمدة المندوبات Z:AG من شيت INVOCES DATA/info وأعمدة الصلاحيات (I مخزن، U مشرف)
 * ويرسلها لقاعدة بيانات لوحة المراقبة. ما يكتب أي شي بالشيت.
 * تشتغل يومياً (installRepsSync) ويدوياً (syncRepsToSupa).
 */
const REPS_SRC = { ID: '1CnWDhmM_ZFSVSdpVmpfuWkdRjP3xsIs-LxsitpC8HRQ', SHEET: 'info', FIRST: 2, LAST: 200 };
const REPS_SYNC_KEY = 'rs_ad752785b56b30e356157a36';

function syncRepsToSupa() {
  const sh = SpreadsheetApp.openById(REPS_SRC.ID).getSheetByName(REPS_SRC.SHEET);
  const n = REPS_SRC.LAST - REPS_SRC.FIRST + 1;
  const v = sh.getRange(REPS_SRC.FIRST, 26, n, 8).getDisplayValues();          // Z:AG
  const norm = s => String(s || '').replace(/[‎‏‪-‮​ ]/g, '').trim().toLowerCase();
  const set = col => new Set(sh.getRange(2, col, 149, 1).getDisplayValues().map(r => norm(r[0])).filter(Boolean));
  const wh = set(9), sup = set(21);                                              // I مخزن، U مشرف
  const rows = [];
  v.forEach((r, i) => {
    const email = norm(r[0]);
    if (!email) return;
    rows.push({ row: REPS_SRC.FIRST + i, email, name: r[1].trim(), phone: r[2].trim(), page: r[3].trim(), sup: r[4].trim(),
                fb: r[5].trim(), date: r[6].trim(), by: r[7].trim(),
                perms: { delegate: true, supervisor: sup.has(email), warehouse: wh.has(email) } });
  });
  const res = UrlFetchApp.fetch(SUPA.URL + '/rest/v1/rpc/reps_sync', {
    method: 'post', contentType: 'application/json', muteHttpExceptions: true,
    headers: { apikey: SUPA.KEY, Authorization: 'Bearer ' + SUPA.KEY },
    payload: JSON.stringify({ p_key: REPS_SYNC_KEY, p_rows: rows }),
  });
  const out = res.getContentText();
  console.log('reps sync: ' + rows.length + ' rows → ' + out.slice(0, 300));
  return out;
}

function installRepsSync() {
  ScriptApp.getProjectTriggers().filter(t => t.getHandlerFunction() === 'syncRepsToSupa').forEach(t => ScriptApp.deleteTrigger(t));
  ScriptApp.newTrigger('syncRepsToSupa').timeBased().everyHours(6).create();
  return syncRepsToSupa();
}
